"""Generate importable workflow templates from reviewable Code-node sources. No credentials are included."""
import json,pathlib,uuid
root=pathlib.Path(__file__).parent
schema=[{'id':k,'displayName':k,'required':False,'defaultMatch':False,'display':True,'type':'string','canBeUsedToMatch':True} for k in ['requestId','workerId','payload','status','result']]
def node(name,type,params,x,y,version=1,**extra):return dict(id=str(uuid.uuid5(uuid.NAMESPACE_URL,'pathtoo/'+name)),name=name,type=type,typeVersion=version,position=[x,y],parameters=params,**extra)
def code(name,filename,x,y):return node(name,'n8n-nodes-base.code',{'jsCode':(root/'code'/filename).read_text()},x,y,2)
def inline(name,script,x,y):return node(name,'n8n-nodes-base.code',{'jsCode':script},x,y,2)
def cond(name,expression,x,y):return node(name,'n8n-nodes-base.if',{'conditions':{'options':{'caseSensitive':True,'leftValue':'','typeValidation':'strict','version':2},'conditions':[{'id':str(uuid.uuid5(uuid.NAMESPACE_URL,'pathtoo/condition/'+name)),'leftValue':'={{ '+expression+' }}','rightValue':True,'operator':{'type':'boolean','operation':'true','singleValue':True}}],'combinator':'and'},'options':{}},x,y,2.2)
def dt(name,op,conditions,x,y,values=None,limit=1):
 p={'resource':'row','operation':op,'dataTableId':{'__rl':True,'mode':'name','value':'pathtoo_deployments'},'matchType':'allConditions','filters':{'conditions':[{'keyName':k,'condition':c,'keyValue':v} for k,c,v in conditions]}}
 if op=='get':p.update(returnAll=False,limit=limit,orderBy=True,orderByColumn='createdAt',orderByDirection='ASC')
 if values is not None:p.update(columns={'mappingMode':'defineBelow','value':values,'schema':schema,'attemptToConvertTypes':False,'convertFieldsToString':False},options={})
 return node(name,'n8n-nodes-base.dataTable',p,x,y,1.1,alwaysOutputData=True)
def workflow(name,nodes,edges):
 connections={}
 for source,target,*branch in edges:
  index=branch[0] if branch else 0
  outputs=connections.setdefault(source,{'main':[]})['main']
  while len(outputs)<=index:outputs.append([])
  outputs[index].append({'node':target,'type':'main','index':0})
 return {'name':name,'nodes':nodes,'connections':connections,'active':False,'settings':{'executionOrder':'v1','saveDataErrorExecution':'none','saveDataSuccessExecution':'none','saveManualExecutions':False,'saveExecutionProgress':False,'executionTimeout':900},'pinData':{},'tags':[]}
def save(name,data):(root/name).write_text(json.dumps(data,indent=2)+'\n')
